function wishEditor(){dialog('Figura da provare',`<form id="wish-form" class="form-fields">${field('w-name','Nome della figura *','','required maxlength="120"')}${textarea('w-note','Appunti / motivo per cui vuoi provarla','','',3)}<div class="dialog-actions"><button type="button" class="btn" data-action="close-modal">Annulla</button><button type="submit" class="btn primary">${I('check')} Aggiungi</button></div></form>`)}
function chooseLessonForFigure(figId){const f=figureBy(figId);if(!f)return;dialog('Inserisci in una lezione',`<form id="attach-form" data-figure="${figId}" class="form-fields">${select('attach-lesson','Scegli una lezione',sortedLessons().map(l=>[l.id,`${l.title} · ${prettyDate(l.date)}`]),'')}${data.lessons.length?'<p class="field-hint">Potrai modificare durata e note del passaggio nella lezione.</p>':'<p class="muted">Crea prima una lezione nella sezione Lezioni.</p>'}<div class="dialog-actions"><button type="button" class="btn" data-action="close-modal">Annulla</button><button type="submit" class="btn primary" ${data.lessons.length?'':'disabled'}>Inserisci figura</button></div></form>`)}
async function compressPhoto(file){if(!file || !file.type.startsWith('image/'))throw new Error('Scegli un’immagine valida.');if(file.size>24*1024*1024)throw new Error('Immagine troppo grande (massimo 24 MB).');const orig=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('Impossibile leggere il file.'));r.readAsDataURL(file)});
 const img=await new Promise((resolve,reject)=>{const x=new Image();x.onload=()=>resolve(x);x.onerror=()=>reject(new Error('Immagine non supportata.'));x.src=orig});const scale=Math.min(1,1200/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',0.78)}
function getForm(id){return new FormData($(id))}
function fsValue(fd,key){return String(fd.get(key)||'').trim()}
async function handleForm(e){const form=e.target;if(!form.matches('form'))return;e.preventDefault();const fd=new FormData(form);
 if(form.id==='figure-form'){
  const id=form.dataset.id;const previous=id?figureBy(id):null;const name=fsValue(fd,'f-name');if(!name){notify('Inserisci un nome per la figura.');return}
  const obj={...previous,id:id||uid(),name,alias:fsValue(fd,'f-alias'),photo:editingPhoto,videoUrl:fsValue(fd,'f-video'),level:Number(fd.get('f-level'))||1,category:fsValue(fd,'f-category'),style:fsValue(fd,'f-style'),progress:fsValue(fd,'f-progress'),difficulty:n(fd.get('f-difficulty')),flexibility:n(fd.get('f-flexibility')),strength:n(fd.get('f-strength')),gripRating:n(fd.get('f-griprating')),grip:fsValue(fd,'f-grip'),contacts:fsValue(fd,'f-contacts'),prerequisites:fsValue(fd,'f-prerequisites'),steps:fsValue(fd,'f-steps'),tips:fsValue(fd,'f-tips'),errors:fsValue(fd,'f-errors'),variations:fsValue(fd,'f-variations'),safety:fsValue(fd,'f-safety'),sourceLevel:fsValue(fd,'f-sourcelevel'),verification:fsValue(fd,'f-verification'),photoOrigin:fsValue(fd,'f-photoorigin'),notes:fsValue(fd,'f-notes'),createdAt:previous?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};
  if(previous)Object.assign(previous,obj);else data.figures.push(obj);
  closeModal();await save();notify('Figura salvata');go('detail',obj.id);return
 }
 if(form.id==='lesson-form'){
  const id=form.dataset.id;const old=id?lessonBy(id):null;const title=fsValue(fd,'l-title');if(!title){notify('Inserisci un titolo.');return}
  const obj={id:id||uid(),title,date:fsValue(fd,'l-date')||today(),group:fsValue(fd,'l-group'),objective:fsValue(fd,'l-objective'),notes:fsValue(fd,'l-notes'),steps:old?.steps||[],status:old?.status||'open',createdAt:old?.createdAt||new Date().toISOString()};
  if(old)Object.assign(old,obj);else data.lessons.push(obj);
  closeModal();await save();notify('Lezione salvata');go('lesson',obj.id);return
 }
 if(form.id==='step-form'){
  const l=lessonBy(form.dataset.id);if(!l)return;const old=form.dataset.step?l.steps.find(s=>s.id===form.dataset.step):null;const linked=fsValue(fd,'s-figure');const obj={id:old?.id||uid(),kind:fsValue(fd,'s-kind'),minutes:Math.max(0,Math.min(300,Number(fd.get('s-minutes'))||0)),name:fsValue(fd,'s-name'),figureId:linked,note:fsValue(fd,'s-note'),done:old?.done||false};if(!obj.name)return notify('Inserisci un nome per l’esercizio.');if(old)Object.assign(old,obj);else l.steps.push(obj);
  closeModal();await save();notify('Passaggio salvato');go('lesson',l.id);return
 }
 if(form.id==='wish-form'){
  const name=fsValue(fd,'w-name');if(!name)return notify('Inserisci il nome.');data.wishlist.push({id:uid(),name,note:fsValue(fd,'w-note'),done:false});closeModal();await save();notify('Aggiunto alle idee');go('wishlist');return
 }
 if(form.id==='attach-form'){
  const l=lessonBy(fsValue(fd,'attach-lesson'));const f=figureBy(form.dataset.figure);if(!l||!f)return;closeModal();stepEditor(l.id,null,f.id);return
 }
}
async function doAction(e){const b=e.target.closest('[data-action]');if(!b)return;if(b.tagName==='A')return;const act=b.dataset.action,id=b.dataset.id,stepId=b.dataset.step;
 if(act==='navigate')return go(b.dataset.view);
 if(act==='export-public')return exportPublicCatalog();
 if(act==='copy-student-link')return copyStudentLink();
 if(act==='view-figure')return go('detail',id);
 if(act==='view-lesson')return go('lesson',id);
 if(act==='add-figure')return figureEditor();
 if(act==='edit-figure')return figureEditor(id);
 if(act==='add-lesson')return lessonEditor();
 if(act==='edit-lesson')return lessonEditor(id);
 if(act==='add-step')return stepEditor(id);
 if(act==='edit-step')return stepEditor(id,stepId);
 if(act==='add-wish')return wishEditor();
 if(act==='close-modal')return closeModal();
 if(act==='clear-filters'){ui.level='all';ui.progress='all';ui.query='';return render()}
 if(act==='clear-photo'){editingPhoto=null;const p=$('#figure-photo-preview');if(p)p.outerHTML=`<div class="preview-empty" id="figure-photo-preview">${I('photo')}</div>`;const inp=$('#f-photo');if(inp)inp.value='';return}
 if(act==='attach-figure-to-lesson')return chooseLessonForFigure(id);
 if(act==='toggle-step'){const l=lessonBy(id),s=l?.steps?.find(s=>s.id===stepId);if(!s)return;s.done=!s.done;await save();return render()}
 if(act==='move-step'){const l=lessonBy(id);if(!l)return;const i=l.steps.findIndex(s=>s.id===stepId),j=i+(b.dataset.dir==='up'?-1:1);if(i<0||j<0||j>=l.steps.length)return;[l.steps[i],l.steps[j]]=[l.steps[j],l.steps[i]];await save();return render()}
 if(act==='delete-step'){const l=lessonBy(id);if(!l)return;if(!confirm('Vuoi eliminare questo passaggio dalla lezione?'))return;l.steps=l.steps.filter(s=>s.id!==stepId);await save();notify('Passaggio eliminato');return render()}
 if(act==='toggle-lesson-done'){const l=lessonBy(id);if(!l)return;l.status=l.status==='done'?'open':'done';await save();notify(l.status==='done'?'Lezione completata':'Lezione riaperta');return render()}
 if(act==='save-lesson-note'){const l=lessonBy(id);if(!l)return;l.notes=$('#lesson-note')?.value||'';await save();notify('Osservazioni salvate');return}
 if(act==='duplicate-lesson'){const l=lessonBy(id);if(!l)return;const dup={...structuredClone(l),id:uid(),title:l.title+' · copia',status:'open',createdAt:new Date().toISOString(),steps:l.steps.map(s=>({...s,id:uid(),done:false}))};data.lessons.push(dup);await save();notify('Lezione duplicata');return go('lesson',dup.id)}
 if(act==='delete-lesson'){if(!confirm('Eliminare questa lezione e tutti i suoi passaggi?'))return;data.lessons=data.lessons.filter(l=>l.id!==id);await save();notify('Lezione eliminata');return go('lessons')}
 if(act==='delete-figure'){if(!confirm('Eliminare questa figura? I passaggi delle lezioni che la citano rimarranno, ma senza collegamento alla scheda.'))return;data.figures=data.figures.filter(f=>f.id!==id);await save();notify('Figura eliminata');return go('figures')}
 if(act==='toggle-wish'){const w=data.wishlist.find(w=>w.id===id);if(!w)return;w.done=!w.done;await save();return render()}
 if(act==='delete-wish'){if(!confirm('Eliminare questa idea?'))return;data.wishlist=data.wishlist.filter(w=>w.id!==id);await save();return render()}
 if(act==='wish-to-figure'){const w=data.wishlist.find(w=>w.id===id);if(!w)return;return figureEditor(null,w.name)}
 if(act==='backup')return exportBackup();
 if(act==='restore')return $('#restoreFile').click();
}
function onChange(e){const el=e.target;
 if(el.classList.contains('public-toggle')){const kind=el.dataset.kind;const item=(kind==='figure'?figureBy(el.dataset.id):lessonBy(el.dataset.id));if(!item)return;item.public=el.checked;save().then(()=>notify(el.checked?'Selezionato per la prossima pubblicazione':'Rimosso dalla prossima pubblicazione'));render();return;}
 if(el.id==='filter-level'){ui.level=el.value;render()}
 else if(el.id==='filter-progress'){ui.progress=el.value;render()}
 else if(el.id==='lesson-filter'){ui.lessonFilter=el.value;render()}
 else if(el.id==='detail-status'){const f=figureBy(ui.figureId);if(f){f.progress=el.value;save();render();notify('Progresso aggiornato')}}
 else if(el.id==='f-photo'&&el.files?.[0]){const before=editingPhoto;const file=el.files[0];el.disabled=true;compressPhoto(file).then(result=>{editingPhoto=result;const p=$('#figure-photo-preview');if(p)p.outerHTML=`<img id="figure-photo-preview" src="${result}" alt="Anteprima della fotografia">`;notify('Foto pronta, salva la figura per conservarla.')}).catch(err=>{editingPhoto=before;notify(err.message)}).finally(()=>{const input=$('#f-photo');if(input)input.disabled=false})}
 else if(el.id==='s-figure'&&el.value){const f=figureBy(el.value),name=$('#s-name');if(f&&name&&!name.value.trim())name.value=f.name}
}
function onInput(e){const el=e.target;if(el.id==='figsearch'){const pos=el.selectionStart;ui.query=el.value;render();const current=$('#figsearch');if(current){current.focus();try{current.setSelectionRange(pos,pos)}catch(_){}}}else if(el.dataset.rate){const o=$('#o-'+el.dataset.rate);if(o)o.textContent=el.value+' / 5'}}
function exportBackup(){const dump={app:'Pole Studio',version:1,exportedAt:new Date().toISOString(),data};const blob=new Blob([JSON.stringify(dump,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='PoleStudio-backup-'+today()+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);notify('Backup esportato: conservalo in File o iCloud Drive.')}
async function importBackup(e){const file=e.target.files?.[0];e.target.value='';if(!file)return;try{if(file.size>120*1024*1024)throw new Error('Il file supera 120 MB.');const obj=JSON.parse(await file.text());if(obj.app!=='Pole Studio'||obj.version!==1||!obj.data||!Array.isArray(obj.data.figures)||!Array.isArray(obj.data.lessons)||!Array.isArray(obj.data.wishlist))throw new Error('Questo file non è un backup valido di Pole Studio.');if(!confirm(`Sostituire l’archivio attuale con il backup del ${new Date(obj.exportedAt||Date.now()).toLocaleDateString('it-IT')}? Le modifiche presenti su questo dispositivo saranno sostituite.`))return;
 data={figures:obj.data.figures,lessons:obj.data.lessons,wishlist:obj.data.wishlist,seedVersion:1};await save();go('home');notify('Backup ripristinato correttamente.')
 }catch(err){notify('Impossibile importare: '+err.message)}}
async function init(){try{db=await openDB();const stored=await readDB();if(stored&&Array.isArray(stored.figures)&&Array.isArray(stored.lessons)&&Array.isArray(stored.wishlist))data=stored;render();document.addEventListener('click',e=>{Promise.resolve().then(()=>doAction(e)).catch(err=>{console.error(err);notify('Non è stato possibile eseguire questa operazione.')})});document.addEventListener('submit',e=>{handleForm(e).catch(err=>{console.error(err);notify('Errore nel salvataggio: '+err.message)})});document.addEventListener('change',onChange);document.addEventListener('input',onInput);$('#restoreFile').addEventListener('change',importBackup);$('#editor').addEventListener('click',e=>{if(e.target===$('#editor'))closeModal()});if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
 }catch(err){console.error(err);$('#app').innerHTML=`<div style="max-width:500px;margin:80px auto;background:white;border-radius:20px;padding:28px"><h2>Salvataggio non disponibile</h2><p>Questo browser non consente l’archivio locale: ${esc(err.message)}. Apri l’app con Safari o Chrome e abilita l’archiviazione dei siti.</p></div>`}}
init();
